pub(super) fn expected_profile_for_cid(
    cid: &str,
    slot: &str,
    state_revision_cid: &str,
    session_descriptor_cid: &str,
    executable_digest: &str,
) -> Result<AdmissionProfile> {
    for profile in [
        AdmissionProfile::V1ChildFree,
        AdmissionProfile::V2ExactReadiness,
    ] {
        let (_, _, expected_cid) = expected(
            slot,
            state_revision_cid,
            session_descriptor_cid,
            executable_digest,
            profile,
        )?;
        if cid == expected_cid {
            return Ok(profile);
        }
    }
    bail!("runtime admission identity mismatch")
}

